CREATE TABLE actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES recovery_cases(id) ON DELETE CASCADE, action_id text UNIQUE NOT NULL, action_type text NOT NULL, idempotency_key text NOT NULL UNIQUE, actor text NOT NULL, authorization_state text NOT NULL, provider text, amount numeric(14,2), evidence_hash text, previous_state text, requested_state text, resulting_state text, verification_state text NOT NULL DEFAULT 'PENDING', approval_state text NOT NULL DEFAULT 'PENDING', created_at timestamptz NOT NULL DEFAULT now())